const D = { density: .55, energy: .55, hue: 190, speed: 1, scale: 1, warp: .2, x: .5, y: .46, seed: 0, style: 'caustics', act: 'drift' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const cl = (v,a,b) => v<a?a:v>b?b:v;
const sty = P.style;
const hz = cl(P.y, .28, .72) * height;
const cx = cl(P.x, .05, .95) * width;
const groundH = Math.max(20, height - hz);
const yOf = t => hz + Math.pow(t, 1.7) * groundH;
const hwOf = t => width * (.045 + t * .95) * .5 * P.scale;
const NR = Math.round(8 + P.density * 16);
const NC = Math.round(6 + P.density * 12);
const H = P.hue;

S.tre = (S.tre||0)*.8 + (A.treble||0)*.2;
S.bass = (S.bass||0)*.8 + (A.bass||0)*.2;
const glow = (.4 + .6*P.energy) * (.55 + .55*K.intensity);
const kick = Math.min(1, K.pulse*(.5+.5*K.intensity) + S.bass*.6);

// real-time seabed scroll + independent caustic phase (never re-phases)
if (S.pt == null || K.t < S.pt) S.pt = K.t;
let dt = K.t - S.pt; S.pt = K.t; dt = cl(dt, 0, .1);
let sp = P.speed * (.5 + .7*K.intensity);
if (P.act === 'surge') sp *= 1 + .9*kick;
if (P.act === 'tide')  sp *= .3 + 1.0*(.5 + .5*Math.sin(K.t*.05 + K.section*.9));
S.scroll = (S.scroll||0) + dt*sp*.5;
S.cph = (S.cph||0) + dt*(.6+.5*P.speed);   // caustic ripple time, continuous
const scroll = S.scroll, cph = S.cph;

// ---- cached water-column base (deep gradient + still seabed sand) ----
const key = width+'x'+height+'|'+sty+'|'+Math.round(H)+'|'+P.seed+'|'+Math.round(P.density*8)+'|'+Math.round(P.y*24)+'|'+Math.round(P.scale*8);
if (!S.base || S.key !== key) {
  const g = S.base && S.base.width===width && S.base.height===height ? S.base : createGraphics(width, height);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const STR = 60;
  // water column above the seabed (light shafts descend)
  for (let i=0;i<STR;i++){ const f=i/STR, y=f*hz;
    let h,s,b;
    if (sty==='sonar'){ h=H; s=70; b=6+5*(1-f); }
    else if (sty==='biolume'){ h=H+10; s=75; b=3+8*(1-f); }
    else { h=H-8; s=60-24*f; b=18+42*(1-f); }  // caustics / stipple
    g.fill(h,cl(s,4,90),cl(b,3,80),100); g.rect(0,y,width,hz/STR+1);
  }
  // seabed sand plane
  for (let i=0;i<STR;i++){ const t=i/STR, y=yOf(t), y2=yOf((i+1)/STR);
    let h,s,b;
    if (sty==='sonar'){ h=H; s=75; b=5+4*t; }
    else if (sty==='biolume'){ h=H; s=70; b=cl(4+5*t,3,16); }
    else { h=H-18+16*t; s=cl(30-14*t,8,60); b=cl(60-40*Math.pow(t,.8),12,72); }
    g.fill(h,cl(s,3,90),b,100); g.rect(0,y,width,(y2-y)+1);
  }
  // static seabed texture
  g.push();
  if (sty==='caustics'||sty==='stipple'){ // scattered sand grains / shells
    g.blendMode(sty==='stipple'?BLEND:ADD);
    for(let i=0;i<200;i++){ const t=.04+.96*fr(i*2), y=yOf(t), hw=hwOf(t);
      const x=cx+(fr(i*2+1)*2-1)*hw; const r=1+t*3.4;
      if(sty==='stipple'){ g.fill(H-14,20,cl(30+40*fr(i*3),10,80),40+40*t); }
      else { g.fill(H+6,18,100,3+6*t); }
      g.ellipse(x,y,r,r); } }
  else if (sty==='biolume'){ /* dark — glow drawn live */ }
  else if (sty==='sonar'){ /* concentric rings drawn live */ }
  g.pop();
  S.base = g; S.key = key;
}
image(S.base, 0, 0);

// ---- CAUSTICS: rippling dappled light on the seabed (the motion floor) ----
if (sty==='caustics'){ push(); blendMode(ADD); noStroke();
  const NCx=NC, NRy=NR;
  for(let r=0;r<NRy;r++){ const t0=r/NRy,t1=(r+1)/NRy; const y0=yOf(t0),y1=yOf(t1);
    const hw0=hwOf(t0),hw1=hwOf(t1);
    for(let c=0;c<NCx;c++){ const u0=c/NCx,u1=(c+1)/NCx;
      const cxr=(u0+u1)*.5, cc=(Math.sin((cxr*7+t0*4+cph)*1.4)+Math.sin((t0*3-cxr*5+cph*1.3)*1.1))*.5;
      const bri=cl(cc,0,1); if(bri<.12) continue;
      const x0a=cx-hw0+u0*2*hw0,x0b=cx-hw0+u1*2*hw0,x1a=cx-hw1+u0*2*hw1,x1b=cx-hw1+u1*2*hw1;
      fill((H+8)%360, 45-20*t0, 100, (10+34*bri)*(.5+.7*glow)*(1+.4*S.tre));
      quad(x0a,y0,x0b,y0,x1b,y1,x1a,y1); } }
  pop(); }

// ---- STIPPLE: hatched engraving light lines ----
if (sty==='stipple'){ push(); stroke(H+6,24,100,0); noFill();
  for(let r=0;r<=NR;r++){ let t=(r-(scroll%1))/NR; if(t<=0||t>1)continue;
    const y=yOf(t),hw=hwOf(t); const shim=.5+.5*Math.sin(t*9+cph*1.4);
    stroke(H+6,20,cl(50+40*shim,20,100),(14+40*t)*(.5+.6*glow)); strokeWeight(.5+t*1.2);
    line(cx-hw,y,cx+hw,y); }
  pop(); }

// ---- SONAR: expanding depth-sounding rings + wire grid ----
if (sty==='sonar'){ push(); noFill();
  for(let ring=0;ring<5;ring++){ let rp=(ring/5 + cph*.12)%1; const t=rp;
    const y=yOf(t),hw=hwOf(t); stroke(H,80,100,(50*(1-t))*(.5+.6*glow)); strokeWeight(.8+ (1-t)*1.6);
    drawingContext.shadowBlur=8*glow; drawingContext.shadowColor=color(H,90,100,80).toString();
    line(cx-hw,y,cx+hw,y); }
  drawingContext.shadowBlur=0;
  for (let c=0;c<=NC;c++){ const u=c/NC,d=(u-.5);
    const xTop=cx+d*width*.03*P.scale, xBot=cx+d*width*1.9*P.scale*(1+P.warp*1.2*d*d*4);
    stroke(H,55,90,26*(.6+.5*glow)); strokeWeight(.7); line(xTop,hz,xBot,height); }
  pop(); }

// ---- BIOLUME: glowing plankton constellations on dark seabed ----
if (sty==='biolume'){ push(); blendMode(ADD); noStroke();
  const NB=Math.round(70+P.density*120);
  for(let i=0;i<NB;i++){ const lane=fr(i*3); let prog=(fr(i*3+1)+scroll*.1*(.5+fr(i*3+2)))%1;
    const t=1-prog; if(t<=.03) continue; const y=yOf(t),hw=hwOf(t);
    const x=cx+(lane*2-1)*hw*.95 + Math.sin(cph*.9+i)*hw*.06;
    const pu=.4+.6*(.5+.5*Math.sin(cph*2+i*1.7)); const sz=(1.2+4*t)*pu;
    fill((H+30+40*fr(i*3+5))%360, 60, 100, Math.min(48,(8+34*t)*pu*(.5+.9*glow)));
    ellipse(x,y,sz,sz); }
  pop(); }

// ---- floating marine snow / bubbles rising (always on) ----
const NP = Math.round(30 + P.density * 70);
push(); blendMode(ADD); noStroke();
for (let i=0;i<NP;i++){
  const lane=fr(i*4);
  let prog=(fr(i*4+2) - cph*.06*(.5+fr(i*4+1)))%1; prog=(prog+1)%1;
  const t=1-prog; if(t<=.02) continue;
  const y=yOf(t) - (1-t)*groundH*.15, hw=hwOf(t);
  const x=cx+(lane*2-1)*hw*.9 + Math.sin(cph*.7+i*1.3)*hw*.08;
  const sz=(1+4*t)*(1+.4*S.tre);
  fill(H+12, 30, 100, Math.min(38,(7+28*t)*(.5+.8*glow)));
  ellipse(x,y,sz,sz);
}
pop();

// gentle surface caustic wash near horizon (partial, safe)
push(); blendMode(ADD); noStroke();
const wash=(kick*.4+K.swell*.4)*glow;
for(let i=0;i<4;i++){ const rr=(4-i)*groundH*.05*(1+wash);
  fill(H, 40, 92, 3+7*wash); rect(0, hz-rr*.4, width, rr); }
pop();

blendMode(BLEND);
drawingContext.shadowBlur = 0;
